def mirrorReflection(p: int, q: int) -> int:
    # Helper to compute gcd
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Find LCM of p and q
    lcm = p * q // gcd(p, q)

    # Number of vertical and horizontal bounces
    vertical_bounces = lcm // q
    horizontal_bounces = lcm // p

    if vertical_bounces % 2 == 0:
        return 0
    elif horizontal_bounces % 2 == 1:
        return 1
    else:
        return 2
